def centers(g):
    H,W=len(g),len(g[0]); out=[]
    for r in range(H):
        for c in range(W):
            if g[r][c]==2:
                n=[(r-1,c),(r+1,c),(r,c-1),(r,c+1)]
                if all(0<=a<H and 0<=b<W and g[a][b]==2 for a,b in n):
                    out.append((r,c))
    return out
def transform(g):
    g=[row[:] for row in g]; H,W=len(g),len(g[0]); cs=centers(g)
    for i in range(len(cs)):
        for j in range(i+1,len(cs)):
            a,b=cs[i],cs[j]
            if a[0]==b[0]:
                r=a[0]; lo,hi=sorted((a[1],b[1]))
                cells=[(r,c) for c in range(lo+1,hi)]
            elif a[1]==b[1]:
                c=a[1]; lo,hi=sorted((a[0],b[0]))
                cells=[(r,c) for r in range(lo+1,hi)]
            else: continue
            if all(g[r][c] in (0,2) for r,c in cells):
                for r,c in cells:
                    if g[r][c]==0: g[r][c]=1
    return g
